"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import Link from "next/link";
import { requestOtp, verifyOtp } from "@/lib/api";
import { saveToken } from "@/lib/auth";
import "@/app/marketing.css";

export default function LoginPage() {
  const [email, setEmail] = useState("");
  const [code, setCode] = useState("");
  const [step, setStep] = useState<"email" | "code">("email");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [shake, setShake] = useState(false);
  const router = useRouter();

  function triggerShake() {
    setShake(true);
    setTimeout(() => setShake(false), 500);
  }

  async function handleRequestOtp() {
    if (!email) return;
    setLoading(true);
    setError("");
    try {
      await requestOtp(email);
      setStep("code");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Something went wrong");
      triggerShake();
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifyOtp() {
    if (code.length < 6) return;
    setLoading(true);
    setError("");
    try {
      const data = await verifyOtp(email, code);
      saveToken(data.access_token);
      router.push("/home");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Invalid or expired code");
      triggerShake();
    } finally {
      setLoading(false);
    }
  }

  return (
    <main className="gesso-auth-page">
      <div className="gesso-auth-bg-layer" />
      <div className="gesso-auth-orb-green" />
      <div className="gesso-auth-orb-red" />

      <Link href="/" className="gesso-auth-header">
        <span className="gesso-auth-brand-mark">Q</span>
        <span>QueryMind</span>
      </Link>

      <div className={`gesso-auth-card ${shake ? "shake" : ""}`}>
        <div>
          <h1 className="gesso-auth-title">
            {step === "email" ? "Sign in to QueryMind" : "Check your email"}
          </h1>
          <p className="gesso-auth-subtitle">
            {step === "email"
              ? "Enter your email to receive a 6-digit one-time passcode."
              : `We sent a code to ${email}`}
          </p>
        </div>

        <div className="gesso-auth-steps">
          <div
            className={`gesso-auth-step-pill ${
              step === "email" ? "active" : "inactive"
            }`}
          />
          <div
            className={`gesso-auth-step-pill ${
              step === "code" ? "active" : "inactive"
            }`}
          />
        </div>

        {step === "email" ? (
          <form
            className="gesso-auth-form"
            onSubmit={(e) => {
              e.preventDefault();
              handleRequestOtp();
            }}
          >
            <label className="gesso-auth-label">
              <span>Work or personal email</span>
              <input
                type="email"
                placeholder="name@company.com"
                required
                className="gesso-auth-input"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </label>

            <button
              type="submit"
              disabled={loading || !email}
              className="gesso-auth-btn-primary"
            >
              {loading ? (
                <>
                  <span className="gesso-spinner" />
                  Sending Code...
                </>
              ) : (
                "Continue with OTP"
              )}
            </button>
          </form>
        ) : (
          <form
            className="gesso-auth-form"
            onSubmit={(e) => {
              e.preventDefault();
              handleVerifyOtp();
            }}
          >
            <label className="gesso-auth-label">
              <span>Enter 6-digit passcode</span>
              <input
                type="text"
                placeholder="000000"
                maxLength={6}
                autoFocus
                className="gesso-auth-input code-input"
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, ""))}
              />
            </label>

            <button
              type="submit"
              disabled={loading || code.length < 6}
              className="gesso-auth-btn-primary"
            >
              {loading ? (
                <>
                  <span className="gesso-spinner" />
                  Verifying...
                </>
              ) : (
                "Verify & Sign In"
              )}
            </button>

            <button
              type="button"
              onClick={() => {
                setStep("email");
                setCode("");
                setError("");
              }}
              className="gesso-auth-btn-back"
            >
              Use a different email address
            </button>
          </form>
        )}

        {error && <div className="gesso-auth-error">{error}</div>}
      </div>
    </main>
  );
}
